```css
/* One stylesheet, no framework: tokens, then the four surfaces (board, bounty, leaderboard, profile). */

:root {
  --bg: #070b14;
  --bg2: #0a1020;
  --panel: #111a2c;
  --panel2: #16213a;
  --ink: #eef3ff;
  --ink2: #aab8d6;
  --ink3: #8595b4;
  --line: #223150;
  --line2: #2f4266;
  --accent: #ffcd5c;
  --green: #5fe3ab;
  --amber: #ffcf6b;
  --red: #ff9f9f;
  --blue: #8cbcff;
  --r: 16px;
  --maxw: 1200px;
}

* { box-sizing: border-box; }

html { -webkit-text-size-adjust: 100%; }

body {
  margin: 0;
  background: radial-gradient(1200px 600px at 78% -12%, #16233d 0%, transparent 60%), var(--bg);
  color: var(--ink);
  font: 16px/1.55 ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

a { color: var(--blue); text-decoration-thickness: 1px; text-underline-offset: 2px; }
a:hover { color: #b6d4ff; }

:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; border-radius: 6px; }

.sr {
  position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px;
  overflow: hidden; clip-path: inset(50%); white-space: nowrap; border: 0;
}

.skip {
  position: absolute; left: -999px; top: 8px; z-index: 20;
  background: var(--accent); color: #0b1020; padding: 8px 14px; border-radius: 8px; font-weight: 700;
}
.skip:focus { left: 8px; }

/* ---------- header ---------- */

.top {
  position: sticky; top: 0; z-index: 10;
  display: flex; align-items: center; gap: 16px; flex-wrap: wrap;
  padding: 12px clamp(14px, 3vw, 28px);
  background: rgb(7 11 20 / 88%);
  backdrop-filter: blur(10px);
  border-bottom: 1px solid var(--line);
}

.brand {
  display: inline-flex; align-items: center; gap: 9px;
  font-weight: 700; font-size: 17px; letter-spacing: -0.01em;
  color: var(--ink); text-decoration: none;
}
.brand em { font-style: normal; font-weight: 500; color: var(--ink2); }
.brand:hover { color: var(--ink); }
.mark {
  width: 18px; height: 18px; border-radius: 5px;
  background: linear-gradient(140deg, var(--accent), #ff9d5c 55%, #8cbcff);
  box-shadow: 0 0 0 1px #0b1020, 0 0 18px -4px var(--accent);
}

.search { flex: 1 1 260px; max-width: 460px; margin: 0; }
.search input {
  width: 100%; padding: 9px 12px;
  background: var(--panel); color: var(--ink);
  border: 1px solid var(--line); border-radius: 10px;
  font: inherit; font-size: 14.5px;
}
.search input::placeholder { color: var(--ink3); }
.search input:focus { border-color: var(--accent); outline: none; box-shadow: 0 0 0 3px rgb(255 205 92 / 22%); }

.net {
  margin: 0 0 0 auto; display: inline-flex; align-items: center; gap: 8px;
  font-size: 12.5px; color: var(--ink2); font-variant-numeric: tabular-nums;
  background: var(--panel); border: 1px solid var(--line); border-radius: 999px; padding: 5px 11px;
}
.led { width: 7px; height: 7px; border-radius: 50%; background: var(--green); box-shadow: 0 0 8px var(--green); }

/* ---------- shell ---------- */

main {
  width: 100%; max-width: var(--maxw); margin: 0 auto;
  padding: clamp(18px, 3vw, 34px) clamp(14px, 3vw, 28px) 56px;
  flex: 1;
}
main:focus { outline: none; }

footer {
  border-top: 1px solid var(--line); padding: 18px clamp(14px, 3vw, 28px);
  color: var(--ink3); font-size: 13px;
}
footer p { margin: 0 auto; max-width: var(--maxw); }
footer .fine { font-size: 12px; margin-top: 6px; }

.loading { color: var(--ink2); padding: 40px 0; }
.noscript { padding: 24px; }

.crumbs { display: flex; gap: 10px; align-items: center; margin: 0 0 14px; font-size: 13.5px; color: var(--ink3); }
.crumbs a { color: var(--ink2); text-decoration: none; }
.crumbs a:hover { color: var(--ink); text-decoration: underline; }

/* ---------- board ---------- */

.head { display: flex; align-items: flex-end; justify-content: space-between; gap: 16px; flex-wrap: wrap; margin-bottom: 6px; }
.head h1 { margin: 0; font-size: clamp(24px, 3.4vw, 32px); letter-spacing: -0.02em; line-height: 1.15; }
.head .sub { margin: 6px 0 0; color: var(--ink2); font-size: 14.5px; }
.head .sub b { color: var(--ink); font-variant-numeric: tabular-nums; }

.toolbar {
  display: flex; flex-wrap: wrap; gap: 8px; align-items: center;
  margin: 18px 0 16px; padding: 10px; border: 1px solid var(--line); border-radius: 12px; background: var(--bg2);
}
.toolbar .label { font-size: 12.5px; color: var(--ink3); text-transform: uppercase; letter-spacing: 0.07em; margin-right: 2px; }
.toolbar .grow { flex: 1 1 auto; }
.toolbar-row { display: flex; flex-wrap: wrap; gap: 8px; }

.chip {
  appearance: none; cursor: pointer; font: inherit; font-size: 13.5px;
  padding: 6px 11px; border-radius: 999px;
  background: var(--panel); color: var(--ink2); border: 1px solid var(--line);
}
.chip:hover { color: var(--ink); border-color: var(--line2); }
.chip[aria-pressed="true"] { background: var(--accent); border-color: var(--accent); color: #0b1020; font-weight: 650; }
.chip:disabled { opacity: .6; cursor: progress; }

.stamp { font-size: 12.5px; color: var(--ink3); font-variant-numeric: tabular-nums; display: inline-flex; gap: 8px; align-items: center; }

.board { display: grid; grid-template-columns: repeat(auto-fill, minmax(330px, 1fr)); gap: 14px; }

.card {
  display: flex; flex-direction: column; gap: 10px;
  padding: 16px; border-radius: var(--r);
  background: linear-gradient(180deg, var(--panel) 0%, #0e1626 100%);
  border: 1px solid var(--line);
  color: var(--ink); text-decoration: none;
  transition: border-color .15s ease, transform .15s ease, box-shadow .15s ease;
}
.card:hover, .card:focus-visible {
  border-color: var(--line2); transform: translateY(-2px);
  box-shadow: 0 12px 26px -18px #000, 0 0 0 1px var(--line2);
}
.card:focus-visible { outline: 2px solid var(--accent); }

.card .top-line { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.card h2 {
  margin: 2px 0 0; font-size: 16.5px; line-height: 1.35; font-weight: 640; letter-spacing: -0.01em;
  display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden;
}

.badge {
  font-size: 11.5px; line-height: 1.4; letter-spacing: 0.02em;
  padding: 3px 8px; border-radius: 999px; border: 1px solid var(--line2); color: var(--ink2); white-space: nowrap;
}
.badge.live { background: rgb(95 227 171 / 14%); color: var(--green); border-color: rgb(95 227 171 / 45%); font-weight: 600; }
.badge.hot { background: rgb(255 159 159 / 13%); color: var(--red); border-color: rgb(255 159 159 / 42%); font-weight: 600; }
.badge.closed { background: transparent; color: var(--ink3); border-color: var(--line); }
.badge.fee { color: var(--accent); border-color: rgb(255 205 92 / 40%); background: rgb(255 205 92 / 9%); }
.badge.free { color: var(--ink2); }

.stats { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 8px; margin-top: 4px; }
.stats .k { display: block; font-size: 10.5px; letter-spacing: 0.075em; text-transform: uppercase; color: var(--ink3); }
.stats .v { display: block; font-size: 15.5px; font-weight: 640; font-variant-numeric: tabular-nums; letter-spacing: -0.01em; }
.stats .v.pot { color: var(--accent); font-size: 17px; }
.stats .v.t-warn { color: var(--amber); }
.stats .v.t-hot { color: var(--red); }
.stats .v.t-done { color: var(--ink3); font-weight: 500; font-size: 14px; }

.cfoot {
  display: flex; justify-content: space-between; gap: 10px; align-items: center;
  border-top: 1px solid var(--line); padding-top: 10px; margin-top: 2px;
  font-size: 12.5px; color: var(--ink2);
}
.cfoot .first { color: var(--ink); font-weight: 600; font-variant-numeric: tabular-nums; }

.empty { border: 1px dashed var(--line2); border-radius: var(--r); padding: 34px 20px; text-align: center; color: var(--ink2); }
.empty h1 { font-size: 22px; }

/* ---------- bounty page ---------- */

.sheet { display: grid; grid-template-columns: minmax(0, 1fr) 316px; gap: 22px; align-items: start; }
@media (max-width: 980px) { .sheet { grid-template-columns: 1fr; } }

.title { margin: 8px 0 10px; font-size: clamp(23px, 3.2vw, 31px); line-height: 1.18; letter-spacing: -0.02em; }
.lede { margin: 0 0 16px; color: var(--ink2); font-size: 15.5px; max-width: 72ch; }

.statgrid { display: grid; grid-template-columns: repeat(auto-fit, minmax(142px, 1fr)); gap: 10px; margin: 0 0 18px; }
.stat { background: var(--panel2); border: 1px solid var(--line); border-radius: 12px; padding: 12px 13px; }
.stat .k { display: block; font-size: 10.5px; letter-spacing: 0.075em; text-transform: uppercase; color: var(--ink3); }
.stat .v { display: block; margin-top: 2px; font-size: 20px; font-weight: 680; font-variant-numeric: tabular-nums; letter-spacing: -0.015em; }
.stat .v.pot { color: var(--accent); }
.stat .v.t-warn { color: var(--amber); }
.stat .v.t-hot { color: var(--red); }
.stat .v.t-done { color: var(--ink2); font-size: 17px; }
.stat .x { display: block; font-size: 12px; color: var(--ink3); margin-top: 2px; }

.panel { background: var(--panel); border: 1px solid var(--line); border-radius: var(--r); padding: 16px 18px; margin: 0 0 16px; }
.panel h2 { margin: 0 0 12px; font-size: 12px; letter-spacing: 0.09em; text-transform: uppercase; color: var(--ink2); font-weight: 650; }

.prose { color: var(--ink); font-size: 15px; max-width: 74ch; }
.prose p { margin: 0 0 12px; }
.prose h3 { margin: 20px 0 8px; font-size: 16px; color: var(--ink); text-transform: none; letter-spacing: 0; }
.prose ul, .prose ol { margin: 0 0 14px; padding-left: 20px; }
.prose li { margin: 0 0 6px; }
.prose code { background: var(--panel2); border: 1px solid var(--line); border-radius: 5px; padding: 1px 5px; font-size: 13px; }
.prose a { color: var(--blue); }
.prose blockquote { margin: 0 0 12px; padding: 8px 14px; border-left: 3px solid var(--line2); color: var(--ink2); }

.rtable { width: 100%; border-collapse: collapse; font-size: 14px; font-variant-numeric: tabular-nums; }
.rtable th { text-align: left; font-size: 11px; letter-spacing: 0.07em; text-transform: uppercase; color: var(--ink3); font-weight: 600; padding: 6px 8px; border-bottom: 1px solid var(--line2); }
.rtable td { padding: 7px 8px; border-bottom: 1px solid var(--line); }
.rtable tr:last-child td { border-bottom: 0; }
.rtable .num { text-align: right; }
.rtable .place { color: var(--ink2); width: 4.5em; }
.rtable .now { color: var(--accent); font-weight: 640; }
.rtable tbody tr:hover { background: #14203a; }

.pairs { margin: 0; display: grid; grid-template-columns: auto 1fr; gap: 7px 14px; font-size: 13.5px; }
.pairs dt { color: var(--ink3); }
.pairs dd { margin: 0; color: var(--ink); font-variant-numeric: tabular-nums; }
.pairs dd a { color: var(--blue); }

.actions { display: flex; flex-wrap: wrap; gap: 10px; align-items: center; margin: 0 0 18px; }
.btn {
  display: inline-flex; align-items: center; gap: 8px; text-decoration: none;
  padding: 9px 14px; border-radius: 10px; font-size: 14px; font-weight: 620;
  border: 1px solid var(--line2); background: var(--panel2); color: var(--ink);
}
.btn:hover { border-color: var(--accent); color: var(--ink); }
.btn.primary { background: var(--accent); color: #0b1020; border-color: var(--accent); }
.btn.primary:hover { background: #ffd876; }
.btn small { font-weight: 500; opacity: .82; }

/* ---------- leaderboard (virtual list) ---------- */

.lb-head { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; margin: 16px 0 10px; }
.lb-head .grow { flex: 1 1 auto; }

.lb-scroll {
  position: relative; overflow-y: auto; overscroll-behavior: contain;
  border: 1px solid var(--line); border-radius: var(--r); background: var(--panel);
  height: min(70vh, 660px);
}
.lb-colhead, .lrow {
  display: grid; grid-template-columns: 58px minmax(0, 1fr) 116px 132px 76px;
  gap: 10px; align-items: center; padding: 0 14px;
}
.lb-colhead {
  position: relative; height: 38px;
  background: var(--panel2); border-bottom: 1px solid var(--line2); border-radius: var(--r) var(--r) 0 0;
  font-size: 10.5px; letter-spacing: 0.08em; text-transform: uppercase; color: var(--ink3); font-weight: 650;
}
.lb-colhead .num, .lrow .num { text-align: right; }
.lb-body { position: relative; }
.lrow {
  position: absolute; left: 0; right: 0; height: 56px;
  border-bottom: 1px solid var(--line); color: var(--ink); text-decoration: none;
  contain: layout style paint;
}
.lrow:hover { background: #16223a; }
.lrow .rank { font-variant-numeric: tabular-nums; font-weight: 680; color: var(--ink2); font-size: 14px; }
.lrow.top1 .rank, .lrow.top2 .rank, .lrow.top3 .rank { color: var(--accent); }
.lrow .who { min-width: 0; }
.lrow .handle { display: block; font-weight: 620; font-size: 14.5px; }
.lrow .title { display: block; font-size: 12.5px; color: var(--ink3); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.lrow .rate { font-variant-numeric: tabular-nums; font-weight: 640; font-size: 15px; color: var(--green); text-align: right; }
.lrow .iv { font-variant-numeric: tabular-nums; font-size: 12.5px; color: var(--ink3); text-align: right; }
.lrow .size { font-variant-numeric: tabular-nums; font-size: 12.5px; color: var(--ink2); text-align: right; }
.lrow .row-main { display: flex; align-items: center; gap: 9px; min-width: 0; }
.mini { width: 26px; height: 26px; border-radius: 50%; background: var(--panel2); border: 1px solid var(--line); flex: none; object-fit: cover; }

@media (max-width: 760px) {
