    const taking = all.filter((b) => accepting(b.deadline, now));
    const pot = taking.reduce((sum, b) => sum + Number(b.potUsd ?? b.rewardAmount ?? 0), 0);

    sub.replaceChildren(
      h('b', null, count(taking.length)),
      ' taking entries of ',
      h('b', null, count(all.length)),
      ' live, ',
      h('b', null, money(pot)),
      ' on the table',
      state.q ? ` · matching “${state.q}”` : '',
      ' · ',
