        h(
          'div',
          { class: 'empty' },
          h('p', null, state.q ? `No live bounty matches “${state.q}”.` : 'No bounty is taking entries right now.'),
          h(
            'button',
            {
              class: 'chip',
              type: 'button',
              'on:click': () => {
                state.closed = true;
                state.q = '';
                paint();
                sync();
              },
            },
            'Show every bounty, closed ones too',
          ),
        ),
